// The `herdr` module: what a mod may ask of Fireflies and the user's machine.
// Generated by Fireflies; do not edit.

export interface ExecResult {
  code: number;
  stdout: string;
  stderr: string;
}

/** Runs a program with the user's real environment (HOME, PATH, auth). 8 MiB output.
 *  `timeout`: milliseconds, defaults to 30,000, capped at 600,000 (10 minutes).
 *  `on`: on that machine (a space's `machine`) through herdr-core, its home by default.
 *  Rejects when it can't start (not installed, no such folder, the machine is unreachable). */
export function exec(command: string, args?: string[], options?: { cwd?: string; on?: string | null; timeout?: number }): Promise<ExecResult>;

/** Runs `hc` (herdr-core) with the given arguments. Add "--json" for machine output. */
export function hc(args: string[]): Promise<ExecResult>;

/** The user's home directory. */
export function home(): string;
/** The app's folder (`~/.config/herdr-app`, or `$HERDR_APP_HOME`): settings.json, keys.json, layouts/. */
export function appHome(): string;

/** Reads UTF-8 text (up to 1 MiB), or null if absent. Runs off the UI thread.
 *  `on`: from that machine (a space's `machine`). */
export function readTextFile(path: string, options?: { on?: string | null }): Promise<string | null>;
/** Writes UTF-8 text only if it still matches expected (null creates a new file).
 * Rejects on a stale snapshot; existing files are replaced atomically. */
export function writeTextFile(path: string, text: string, expected: string | null): Promise<null>;

/** Syntax spans of `text` from a tree-sitter grammar: `[start, end, name]`, ordered and
 *  non-overlapping, offsets in JavaScript string units. `name` is the grammar's capture name
 *  (`keyword`, `function.method`, `string.escape`, `comment`, `type.builtin`, ...): color the
 *  root name and let dotted ones fall back to it. `language` is a language id, alias or a path
 *  (`"rust"`, `"ts"`, `"src/main.rs"`). Empty for languages without a grammar and text over 2 MB. */
export function highlight(text: string, language: string): [number, number, string][];
/** The editor's language id for a path or name (`"src/a.tsx"` → `"tsx"`, `"Cargo.lock"` →
 *  `"toml"`), or null when unknown. */
export function languageOf(pathOrName: string): string | null;

/** A language server for code a mod shows (this machine). Starts `argv` in `root` (or joins the
 *  session already running it there: one server per argv and root, shared by every mod copy),
 *  initializes it (utf-16 positions; `settings` go out as `initializationOptions`, answer its
 *  `workspace/configuration` and follow in `workspace/didChangeConfiguration`) and resolves once
 *  it's ready with its `id` and `capabilities`. Rejects when it can't start. The copy keeps it until
 *  `lspRelease(id)` or the copy goes; a server no copy keeps runs on for `idle` seconds (default 90,
 *  at most 4 h, the longest any starter asked for), and of the servers nobody uses at most 2 stay:
 *  past that the least recently used stops first. A copy joining while the server works gets the
 *  `$/progress` begun and not ended (with the last report's words) first. Fireflies only carries
 *  messages: opening documents, keeping them in sync and reading diagnostics is yours. */
export function lspStart(options: { argv: string[]; root: string; settings?: object | null; idle?: number }): Promise<{ id: number; capabilities: unknown }>;
/** Sends a request and resolves with its result; rejects with the server's error, after 30 s,
 *  or when the server exits. `key`: a later request of this copy with the same key replaces this
 *  one (the server hears `$/cancelRequest`, this rejects with "cancelled"). */
export function lspRequest(id: number, method: string, params?: unknown, options?: { key?: string }): Promise<unknown>;
/** Sends a notification (`textDocument/didOpen`, `didChange`, `didSave`, `didClose`, ...). Open
 *  documents are counted per mod copy: the server hears `didOpen` once (a later copy's becomes a
 *  `didChange` with its text, and that copy gets the file's last `publishDiagnostics` at once) and
 *  `didClose` when the last copy closes the file or goes. */
export function lspNotify(id: number, method: string, params?: unknown): void;
/** The next notification the server sent this copy: `{ method, params }`
 *  (`textDocument/publishDiagnostics`, `$/progress`, `window/logMessage`, ...). `$/exit` with
 *  `params.stderr` (its last lines) when the server is gone. */
export function lspNextMessage(id: number): Promise<{ method: string; params: unknown }>;
/** This copy no longer needs the session. */
export function lspRelease(id: number): void;
/** The running servers: `{ id, argv, root, users, alive, ready, stderr }`. */
export function lspSessions(): { id: number; argv: string[]; root: string; users: number; alive: boolean; ready: boolean | null; stderr: string[] }[];

/** Files under `root` (this machine) that fuzzily match `query`, best first (fff: typo-resistant,
 *  git-ignored files left out, the index kept current while it's used). `ranges`: the matched
 *  characters of `path` (relative to root), `git`: "M" "A" "U" "D" "R" "!" or null. `scanning`:
 *  the first index of a big folder isn't complete yet; ask again. An empty query lists files.
 *  Rejects for a missing folder, and for home or / as a whole. */
export function findFiles(root: string, query: string, options?: { limit?: number }): Promise<{ files: { path: string; git: string | null; ranges: [number, number][] }[]; total: number; indexed: number; scanning: boolean }>;
/** Lines under `root` matching `query` (fff's live grep, ~150 ms budget, git-ignored files left
 *  out): `mode` "plain" (default), "regex" or "fuzzy"; `case` "smart" (default), "sensitive",
 *  "insensitive". `line` is one-based; `col` and `ranges` in the line's string units. `error`: a
 *  regex that didn't compile (searched as plain text). */
export function grep(root: string, query: string, options?: { limit?: number; mode?: "plain" | "regex" | "fuzzy"; case?: "smart" | "sensitive" | "insensitive" }): Promise<{ matches: { path: string; line: number; col: number; text: string; ranges: [number, number][] }[]; files: number; truncated: boolean; error: string | null; scanning: boolean }>;

/** This copy holds unsaved work: closing its pane or tab asks the person first (scripts must pass
 *  `confirmed`), showing `note` ("picker.rs: unsaved changes"). null or "" when it's saved again. */
export function setUnsaved(note: string | null): void;

/** The agents people can start from a menu (entries with `run` in programs.json), most picked
 *  first, and whether each is installed: asked of the shell agents start in (on another machine,
 *  `on`, its login/interactive shell when supported), at most once a minute per machine.
 *  Rejects if the check fails; failed checks are not cached. Start one with its `run` as `argv`. */
export function knownAgents(options?: { on?: string | null }): Promise<(Program & { run: string[]; installed: boolean })[]>;

/** Opens the system's folder picker (this machine). Resolves with the chosen folder, or null
 *  when the person cancels. `prompt`: the confirm button's text (default "Open"). */
export function pickFolder(options?: { prompt?: string }): Promise<string | null>;
/** Opens the system's file picker (this machine), files only: an .app bundle counts as one.
 *  Resolves with the chosen path, or null when cancelled. */
export function pickFile(options?: { prompt?: string }): Promise<string | null>;

/** Plays "done" or "blocked" (the attention sounds, or the files settings.json names), or an MP3
 *  file (absolute, or relative to ~/.config/herdr-app). */
export function playSound(sound: string): null;

/**
 * Runs a command, the same ones keys.json binds (`herdr-app commands` lists them all with their
 * arguments). Structural commands fail while their machine's layout is unavailable.
 * Mod props are stored as given, never machine-qualified. Most commands apply right after
 * the call returns; terminal.keep/park finish in the background and toast on failure.
 * A rename without a name is asked for;
 * "" gives the space or tab Fireflies' automatic name again. The main ones:
 * Spaces: space.new {name?, folder?, tab?, argv?, task?, machine?}, space.close {id?}, space.rename {id?, name},
 *   space.move {id, index}, space.select {index | id}, space.next, space.prev.
 * Tabs: tab.new {name?, space?, folder?, argv?, task?} (argv: an agent, task: its first message)
 *   or {name?, space?, mod, props?} (a tab whose only pane is a mod),
 *   tab.close {id?}, tab.rename {id?, name}, tab.move {id, index}, tab.select {index | id},
 *   tab.next, tab.prev.
 * Panes: pane.split {direction: "right" | "down" | "left" | "up" | "auto", pane?, argv? | mod?, props?}
 *   (left/up: before the pane; auto: below a pane in a side-by-side split, right of one in a stacked
 *   split or a lone pane), pane.split {edge: "right" | "left" | "top" | "bottom", px?, tab?, argv? | mod?, props?, folder?}
 *   (a new pane along that side of a whole tab, default the shown one, spanning it; px: its fixed width
 *   or height), pane.close {pane?}, pane.zoom {pane?},
 *   pane.font_bigger|font_smaller|font_reset {pane?} (that pane's terminal text size, see PaneInfo.font_zoom),
 *   pane.float {pane?} (its terminal floats over the tab; the pane goes, as terminal.park),
 *   pane.park {pane?, index?} (a chip in its tab's bottom row, still running; index moves a parked chip, 1 = first),
 *   pane.unpark {pane?, target?, edge?} (back where it was, or beside target; target without edge: in its place),
 *   pane.focus {pane | terminal}, pane.go {direction}, pane.swap {pane?, direction | target},
 *   pane.move {pane?, tab? | target?, edge?, space?, name?} (to another tab on its machine, or a new tab; keeps running),
 *   pane.equalize {scope?: "all" | "row" | "column", pane?} (even shares: every row and column of the tab, or the
 *   pane's nearest row or column; fixed px sizes stay). Pane menus get target { pane, terminal }.
 * Terminals: terminal.open {argv?, folder?, place?: "tab" | "right" | "down" | "left" | "up" | "auto" | "float", pane?, view?, show?}
 *   (pane: the one right/down/left/up/auto splits, default the focused one; "float": no pane, floating over the tab
 *   in the "terminal-peek" overlay; closing it leaves it running), terminal.kill {terminal},
 *   terminal.keep {terminal, place?, pane?} (a running one without a pane, e.g. a sub-agent, gets one; places as terminal.open but no float),
 *   terminal.park {terminal} (its pane goes, it keeps running; the menu's "Send back"),
 *   terminal.peek {terminal, float?, view?, show?} (peek over the tab, with keep-as-tab, dock-right and close; float: as a float),
 *   float views: terminal.open {place: "float", view?: {mod, props?, name?}, show?: 0 | 1} and terminal.peek {terminal,
 *   float: true, view?, show?} make the float's body a stack of the terminal (0) and that mod (1), showing `show`
 *   (default 0; peek with the same view on the one floating now only switches), float.view {index: 0 | 1} (switch the
 *   open float and give the shown one the keyboard: the terminal, or the mod if its mod.json is focusable),
 *   terminal.show {terminal?, pane?} (shown in the pane for now, in place of its own), terminal.copy, terminal.paste,
 *   terminal.right_click {to: "program" | "menu", terminal?} (right-clicks to a program that takes the mouse; Shift: the menu).
 *   terminal.scroll {lines | pages | to: "top" | "bottom", terminal?} (Fireflies' view of the history: negative goes up; pages may be fractional).
 * Agents: agent.next, agent.prev (the agents list's order), agent.focus {terminal} (sub-agents too).
 * Layout (the shown layout's nodes by id): layout.toggle|show|hide {id}, layout.resize {id, px | weight},
 *   layout.focus {id} (the keyboard to a shown block whose mod.json says focusable: it gets "focus" from nextCommand()),
 *   layout.select {stack, child}, layout.set {layout} (personal trees; shipped layouts: click/look fields only), layout.switch {name?} (no name: the next one).
 *   layout.clone {name, as?} duplicates and switches; mod.clone {name, as?} duplicates a mod.
 *   Layout clones copy the look and clicks as-is. Layout looks win; settings fill unset fields; theme picks override both.
 *   Mod clones rewrite their own asset prefixes and self-opening overlay names.
 *   Default clone name: <name>-copy; an existing name is refused. Clones record cloned_from: {name, version}.
 *   Shipped layouts/mods are replaced at start; edits move to <name>-edited.
 *   Fireflies (main) inherits settings; Fireflies 98 and Terminals bring their own look. Clone to change shipped looks beyond theme picks.
 *   layout.reset {name?} resets a shipped layout and its clicks.
 * App: mod.open {name}, overlay.close {id?}, overlay.resizable {id, resizable}, app.help, app.reset, app.theme {name}, app.zoom_in|zoom_out|zoom_reset.
 * Mods: "<mod>.<command>" delivers <command> to that mod's nextCommand().
 */
export function run(name: string, args?: Record<string, unknown>): null;

export type Status = "working" | "blocked" | "done" | "idle";

/** A named piece of work in a space: shared through that machine's core doc.
 * Remote space/tab/pane ids have a machine/ prefix; labels on that machine omit it.
 * Selection, focus, zoom and settled state belong to this screen only. */
export interface TabInfo {
  id: string;
  /** Position in its space, from 1. */
  index: number;
  /** Its name, or its position ("2") when nobody named it. */
  name: string;
  /** Someone named it (tab.rename, tab.new {name}). */
  named: boolean;
  /** The one its space shows. */
  active: boolean;
  /** Most urgent agent status in it, or null. */
  status: Status | null;
  /** Panes in its arrangement (parked ones not counted). */
  panes: number;
  /** Panes parked in its bottom row (pane.park). */
  parked: number;
  zoomed: boolean;
  /** Put away on this screen (tab.settle): lists hide it or fold it; it keeps running and comes back
   *  when shown or when an agent in it needs the person. */
  settled: boolean;
  /** ms since the epoch, or null. */
  settled_at: number | null;
  /** When something in it last changed state (null: nothing since the app started). */
  changed_at: number | null;
  /** Since when an agent in it has been working, or null. */
  working_since: number | null;
}

export interface SpaceInfo {
  id: string;
  index: number;
  /** Its name, or where its first terminal is now (repo, else folder, "~" at home)
   *  when nobody named it. */
  name: string;
  /** Someone named it (space.rename, space.new {name}). */
  named: boolean;
  /** Where its new terminals start (on its machine; empty: that machine's home). */
  folder: string;
  /** `folder` was chosen (space.new {folder}, space.folder): the space's repo is
   *  there. Otherwise it's only where the space was made; go by its terminals'
   *  live folders. */
  attached: boolean;
  /** The machine it lives on (`hc machine ls`), null for this one. */
  machine: string | null;
  /** The git branch of the terminal it shows first, if any. */
  branch: string | null;
  /** The shown space. */
  active: boolean;
  /** Most urgent agent status in it (blocked > done > working > idle), or null. */
  status: Status | null;
  tabs: TabInfo[];
}

/** Machines' layout documents on this connection. Null names this computer.
 * Loading ends after the first read, including failures; unavailable includes offline cores. */
export function machines(): { name: string | null; layout: "loading" | "ready" | "unavailable" }[];

/** Spaces in order. Mods re-render when they change. */
export function spaces(): SpaceInfo[];

/** How a terminal shows, from the app's program table (programs.json): the agent's own
 *  report, else the program it runs. Draw `icon` with `svg(icon)` in a color when `tint`
 *  (a one-color glyph), else `image(icon)`. `tile` / `color`: a colored tile with the glyph
 *  on it, for layouts that want one. */
export interface Program {
  /** The table's key, e.g. "claude", "nvim", "shell", "program" (not listed), "agent". */
  key: string;
  /** For people: "Claude Code", "Neovim", "zsh", or the process name. */
  name: string;
  /** A path in the home folder, e.g. "icons/nvim.svg". */
  icon: string | null;
  tint: boolean;
  tile: string | null;
  color: string | null;
  shell: boolean;
  agent: boolean;
}

export interface AgentInfo {
  address: string;
  pane: string;
  space: string;
  space_name: string;
  tab: string;
  tab_index: number;
  tab_name: string;
  /** "done" means it finished while you weren't looking; it becomes "idle" once you look
   *  (here or on another herdr-core client). */
  status: Status;
  /** What the agent reported (OSC 7501 `app`), e.g. "claude-code", "pi", "codex". */
  app: string | null;
  program: Program;
  /** The terminal's title. */
  title: string;
  /** Higher = changed more recently. */
  seq: number;
  /** Pinned with `terminal.pin`, on any herdr-core client. */
  pinned: boolean;
  focused: boolean;
  /** Working, but waiting on a shell command it started (a long build, `hc wait`):
   *  a shell under its process that began with its current step. Only for agents on
   *  this machine (macOS, Linux); false elsewhere. */
  command: boolean;
}

/** Terminals whose program reports a status (agents), in space, tab, pane order. Live. */
export function agents(): AgentInfo[];

export interface PaneInfo {
  pane: string;
  /** null for a mod pane (`pane.split {mod}`): then `mod` names it, and only
   *  pane, mod, props, tab, title, focused, zoomed, font_zoom and movable are set. */
  terminal: string | null;
  mod?: string;
  /** A mod pane's props, as given (read-only): a copy can find its own pane by a unique prop. */
  props?: unknown;
  tab: string;
  /** The terminal's title (what the program set), or the mod's name. */
  title: string;
  /** Its live folder, and the git branch there. */
  cwd: string | null;
  branch: string | null;
  /** Agent status if the program reports one, else null. */
  status: Status | null;
  app: string | null;
  program: Program;
  focused: boolean;
  zoomed: boolean;
  /** This pane's terminal text size on top of the app's (pane.font_bigger/smaller/reset):
   *  1 = the app's size, steps of 0.1 from 0.5 to 3. Always 1 for a mod pane. */
  font_zoom: number;
  /** The app's top-center grip can rearrange this pane. False when zoomed or alone. */
  movable: boolean;
  /** Parked in its tab's bottom row (pane.park): not on screen, still running. */
  parked: boolean;
}

/** Every pane in every tab. A pane header mod finds its own with
 *  `panes().find((p) => p.pane === props().pane)`. Live. */
export function panes(): PaneInfo[];

/** Sets agent.next / agent.prev order to match the list a mod displays.
 *  Call when rendering the list. In memory only; missing agents are ignored, new agents
 *  are appended in model order. Without a supplied order, navigation uses model order. */
export function setAgentOrder(addresses: string[]): null;

/** Every core terminal as `hc ls --json` describes it (address, argv, name, template, parent,
 *  labels, state, ...), with `status` as a plain word, the agent's report in `report`,
 *  `program` (see Program), and `floating`: true for the one floating over the tab now
 *  (terminal.open {place: "float"}, pane.float), else false. The floating one also has
 *  `floating_view: number` (the view its float shows: 0 the terminal, 1 its `view` mod; 0 without
 *  one) and `float_views: string[] | null` ([its program's name, view.name ?? view.mod]; null
 *  without a view); others have null for both. Parent addresses use the same machine names as `address`;
 *  parents on this computer use bare terminal IDs. Parents that cannot be mapped
 *  stay as the core reported them. Live. */
export function terminals(): readonly unknown[];

/** Actual terminal/pane focus. `space` and `tab` are the current window context.
 *  Clicking a visible layout terminal block, or pane.focus {terminal}, focuses that block:
 *  `terminal` and `cwd` describe it; `pane` and `shown` are null, not its source pane.
 *  Implicit pane split/close/zoom/go/swap and terminal.show fail in that case, as do
 *  terminal.open/keep with place right/down/left/up/auto and no pane. An explicit pane id targets a model pane.
 *  A terminal in a window (openOverlay with a layout) that has the keyboard is reported
 *  the same way (`pane` and `shown` null); implicit pane commands still act on the
 *  focused pane under the window.
 *  pane.focus {terminal} prefers the first visible layout terminal block, then a model pane.
 *  `shown`: terminal.show replacement, if any. `agent`: the agent an agent block shows.
 *  `terminal` is null for mod panes. `block`: the layout block holding the keyboard
 *  (a focusable mod reached with pane.go or layout.focus), else null; with no space yet
 *  only `block` is set. Live. */
export function focused(): { space: string | null; tab: string | null; pane: string | null; terminal: string | null; shown: string | null; agent: string | null; cwd: string | null; block: string | null } | null;

/** The shown layout (layouts/<name>.json). Its name is shared("layout").
 *  Root `terminal_menu?: string` chooses a terminal right-click menu mod (default: "menu").
 *  Unknown names warn and fall back to "menu". This replaces the menu, not its items.
 *  Opens a pointer popup with mod.json overlay width/height (default 220×260). */
export function layout(): unknown;

/** The names of every layout in layouts/ (main first). */
export function layouts(): string[];

/** Every command the app runs: its name, arguments and what it does (as `herdr-app commands`).
 *  Mods' own `<mod>.<command>`s aren't listed. */
export function commands(): { name: string; args: { name: string; required: boolean }[]; about: string }[];

/** The window, for layouts that draw their own title bar (`"titlebar": "none"`). `buttons`:
 *  the system draws no window buttons, so draw them (`window.minimize`, `window.maximize`,
 *  `window.close`); on macOS the traffic lights always stay. Live. */
export function window(): {
  platform: "linux" | "macos" | "windows";
  titlebar: "system" | "none";
  buttons: boolean;
  maximized: boolean;
  fullscreen: boolean;
  active: boolean;
};

/** For a floating mod: where it sits now. `vertical` on the left/right edges, horizontal on
 *  top/bottom; while dragged, where it would land. `hovered` is true while the pointer is on it
 *  (or it's dragged); a `peek` drawer is open then. Null for mods that don't float. */
export function placement(): {
  edge: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
  vertical: boolean;
  hovered: boolean;
  dragging: boolean;
} | null;

/** Every theme color by name: background (the terminals'), surface, canvas (behind cards),
 *  chrome (sidebars and bars), popover, raised, hover, selected, border, input, foreground,
 *  muted, dim, accent, accent_foreground, solid and solid_foreground (a primary button: ink on
 *  paper, paper on ink), selection, working, blocked, done, idle, unknown, ansi0..ansi15.
 *  Light and dark themes name the same colors, so a mod that uses them follows both. */
export function theme(): Theme;

type Color = import("gpui-kit").Color;

/** The resolved theme (settings.rs `resolve`): every name below is in every theme, as `#rrggbb`
 *  or `#rrggbbaa`. `terminal_foreground` is the terminal's text, `foreground` the panels'. */
export interface Theme {
  readonly background: Color;
  readonly terminal_foreground: Color;
  readonly foreground: Color;
  readonly surface: Color;
  readonly canvas: Color;
  readonly chrome: Color;
  readonly popover: Color;
  readonly raised: Color;
  readonly hover: Color;
  readonly selected: Color;
  readonly border: Color;
  readonly input: Color;
  readonly muted: Color;
  readonly dim: Color;
  readonly accent: Color;
  readonly accent_foreground: Color;
  readonly solid: Color;
  readonly solid_foreground: Color;
  readonly ring: Color;
  readonly selection: Color;
  readonly cursor: Color;
  readonly working: Color;
  readonly blocked: Color;
  readonly done: Color;
  readonly idle: Color;
  readonly unknown: Color;
  readonly ansi0: Color;
  readonly ansi1: Color;
  readonly ansi2: Color;
  readonly ansi3: Color;
  readonly ansi4: Color;
  readonly ansi5: Color;
  readonly ansi6: Color;
  readonly ansi7: Color;
  readonly ansi8: Color;
  readonly ansi9: Color;
  readonly ansi10: Color;
  readonly ansi11: Color;
  readonly ansi12: Color;
  readonly ansi13: Color;
  readonly ansi14: Color;
  readonly ansi15: Color;
}

/** Every theme `app.theme` can use (presets, then `themes/*.json`), each with its colors and
 *  whether it's light. */
export function themes(): readonly { readonly name: string; readonly light: boolean; readonly colors: Theme }[];

/** The font families on this machine, by name. */
export function fonts(): string[];

/** Fireflies' and herdr-core's versions and what's waiting. `app.updates`: false for a build from
 *  source (it never updates). `core.managed`: the package manager that owns the core (homebrew,
 *  nix, mise), which the app never updates. `checked`: unix seconds of the last successful
 *  check; null before success or after a failed check.
 *  `checks`: anything is checked at all (not in a build from source); `checking`: looking now
 *  (`app.check_updates` starts a look). */
export function updates(): {
  app: { version: string; ready: string | null; updates: boolean };
  notes: { version: string; date: string; items: { headline: string; detail: string; fixed: boolean; media: { path: string; width: number; height: number }[] }[]; spotlight: boolean }[];
  core: { version: string | null; managed: string | null; ready: string | null; updating: boolean; error: string | null };
  checked: number | null;
  checks: boolean;
  checking: boolean;
};

/** Record only spotlight versions actually shown expanded, never collapsed headlines. */
export function presentUpdateNotes(versions: string[]): null;

/** The feedback form's GitHub issue: `title` (the given one, else the message's first line),
 *  `body` (the message plus app, herdr-core and OS versions) and `url`, the prefilled
 *  new-issue page (cut to fit a link). Nothing is sent: open `url` with `app.open_url`. */
export function feedbackIssue(title: string, message: string): { title: string; body: string; url: string };

/** What the app runs with: the shown layout's look (theme name, fonts, sizes, terminal
 *  padding and opacity) with the person's zoom and sounds. */
export function settings(): Settings;

/** One language's editor settings (settings.json `editor`, `editor.languages.<id>`), as written. */
export interface EditorLanguage {
  readonly tab_size?: number;
  readonly insert_spaces?: boolean;
  readonly soft_wrap?: boolean;
  readonly format_on_save?: boolean;
  readonly format?: readonly string[];
  /** An argv to run, or false to run none. */
  readonly server?: false | readonly string[];
  /** Handed to the language server as is: parse it there. */
  readonly server_settings?: unknown;
}

/** settings.rs `Settings`: the look the app runs with, and the person's settings.json. */
export interface Settings {
  readonly font_family: string;
  readonly font_size: number;
  readonly font_ligatures: boolean;
  readonly ui_font_family: string;
  readonly ui_font_size: number;
  /** How big the whole app is drawn (1 = as designed). */
  readonly zoom: number;
  /** The theme showing: a preset or a file in themes/. */
  readonly theme: string;
  readonly theme_light: string;
  readonly theme_dark: string;
  /** Whether the window is dark now. */
  readonly dark: boolean;
  readonly colors: Theme;
  readonly pane_scrollbars: boolean;
  /** Between a terminal's edge and its text, px: [x, y]. */
  readonly terminal_padding: readonly [number, number];
  readonly terminal_opacity: number;
  readonly clipboard_write: boolean;
  readonly minimum_contrast: number;
  readonly links: "app" | "system";
  readonly option_as_alt: "auto" | "off" | "on" | "left" | "right";
  readonly sounds: { readonly enabled: boolean; readonly done?: string; readonly blocked?: string };
  readonly editor: EditorLanguage & {
    readonly vim?: boolean;
    readonly leader?: string;
    readonly languages?: { readonly [language: string]: EditorLanguage };
  };
  readonly files: { readonly hidden?: boolean; readonly ignored?: boolean };
}

/** Every key binding: { section, keys, action }. */
export function keys(): { section: string; keys: string; action: string }[];

export interface OverlaySpec {
  /** One mod, or `layout`. */
  mod?: string;
  props?: Record<string, unknown>;
  /** Blocks as in layouts/*.json (`{ terminal: "t7" }` blocks too), instead of `mod`. Its mods get
   *  `props().overlay`. Esc goes to its terminals (agents use it), so give it a way to close.
   *  Closes itself when its terminal ends. A terminal nothing else showed gets the size it had
   *  before back when it closes (a small window doesn't leave it small). */
  layout?: unknown;
  /** dialog: centered, dims the window. popup: at `at` (default: the pointer).
   *  window: stays open until closed (no dimming, a click beside it doesn't close it, Esc goes to
   *  the mod); dragged by any press the mod doesn't stop (`cx.stop_propagation()` on its controls'
   *  mouse down) and stays where dropped; the one pressed last is on top; at `at` (its top left),
   *  else centered; as big as its content unless width/height. It doesn't take the keyboard
   *  when it opens (a mod may focus itself). A layout switch closes windows. */
  kind?: "dialog" | "popup" | "window";
  /** A window or popup with the layout's dialog dim (its `scrim`) behind it; a click on the
   *  dim closes it, like a dialog's (this fork). Dialogs always have it; a popup hanging from
   *  a button shouldn't ask. */
  scrim?: boolean;
  /** A dialog a click beside it doesn't close (Esc and its own buttons still do). */
  modal?: boolean;
  /** "none": no border, rounded corners, shadow or background around it; the mod draws its own. */
  frame?: "none";
  /** A window's name: it remembers where it was dropped and opens there next time; opening the
   *  same key again replaces the open one, in its place. */
  key?: string;
  /** With `key`: the window also reopens on the next start (and when its layout shows again),
   *  until it's closed. Only the window comes back: a mod keeps its own state (`shared`). */
  keep?: boolean;
  /** A window people resize by its edges and corners: never below `min` (px, default 120×80)
   *  nor bigger than the app window, keeping `aspect` (width / height) once `chrome` (px taken
   *  by a bar or border, width and height) is taken off. With `key`, its size is remembered.
   *  `run("overlay.resizable", { id, resizable })` changes it while open (a new aspect refits it). */
  resizable?: boolean | { min?: [number, number]; aspect?: number; chrome?: [number, number] };
  /** px, or up to 1: a share of the window. */
  width?: number;
  height?: number;
  at?: "pointer" | { x: number; y: number };
}

/** Shows a mod (or a layout) above everything. Returns its id. The mod gets `props().overlay` = that id. */
export function openOverlay(spec: OverlaySpec): string;

/** Closes an overlay (mods close themselves with closeOverlay(props().overlay)). Esc closes the top
 *  dialog or popup. A kept window closed this way stays closed. */
export function closeOverlay(id: string): null;

/** Posts a notification. Shown by the `toast` mod (replaceable), which runs `action` when clicked.
 *  Fireflies posts one itself when an agent needs you or finished while you weren't looking. Returns its id. */
export function notify(n: {
  title: string;
  body?: string;
  level?: "info" | "success" | "warning" | "error";
  timeout?: number;
  icon?: string;
  action?: { name: string; args?: Record<string, unknown> };
}): string;

/** The props this copy of the mod was given in the layout (or overlay).
 *  A layout's terminal_menu mod gets {tab: "pane", target: {pane: string, terminal: string}, overlay: string}.
 *  Target names the clicked pane/terminal, not necessarily the focused one; pass it to actions.
 *  Close the popup with closeOverlay(props().overlay). */
/** Size is not a prop: root div/h_flex/v_flex.on_size_change reports logical px.
 * The exported View may implement async close(cx) for bounded final cleanup. */
export function props(): unknown;

/** Reads a value every mod can see (persisted). `unknown`: any mod, or an older version of this
 *  one, may have written it, so parse it where it's read (a TypeScript mod: guard.ts `readShared`). */
export function shared(key: string): unknown;

/** Sets a shared value; every mod re-renders so it can react. */
export function setShared(key: string, value: unknown): null;

/**
 * Waits for the next key command for this mod ("alt-s": "<mod>:<command>" in keys.json).
 * With "focusable": true in mod.json, pane.go can move onto this copy and send "focus".
 * Focus your own handle then (this.handle.focus()) and handle keys with on_key_down.
 * The copy gets "focus" again when a popup over it closes. Leave with pane.go.
 *   cx.spawn(async (cx) => { for (;;) { const c = await nextCommand(); ...; cx.notify(); } });
 */
export function nextCommand(): Promise<string>;

/**
 * Waits for changes under a folder and returns absolute paths in batches.
 * On Linux, Git-ignored directories and Git's object database are skipped; trees
 * above 4096 non-ignored directories reject the watch, so use a timer fallback.
 * macOS and Windows watch recursively, including ignored directories.
 * Pending paths are bounded: a batch containing the root means refresh everything.
 * Shared by every mod. Files also refreshes on its 10-second timer.
 *   cx.spawn(async (cx) => { for (;;) { await watchFolder(dir); this.reload(); cx.notify(); } });
 * Watch what you show, not a whole home folder (node_modules is a lot of events).
 */
export function watchFolder(path: string): Promise<string[]>;

/** HUP (Herdr Preview Dev, interface native-view/0): where a native view's content comes from.
 *  Web: `url` (http/https; `localhost:3000` style input is normalized, never searched) or a local
 *  HTML `path` (absolute; `trust` "static" disables page scripts, "interactive" allows them; `root`
 *  bounds which sibling files it may read, default its folder). pdf / media / quicklook: `path`. */
export interface NativeViewProps {
  kind: "web" | "pdf" | "media" | "quicklook" | "inspector" | "pip"; url?: string; path?: string; trust?: "static" | "interactive"; root?: string;
  /** Inspector only: the web view to inspect, the `of` its `web.inspect` action returned. */
  of?: string;
  /** Web only: the page zoom (WKWebView pageZoom), 1 = 100% (default), clamped to 0.25–5.
   *  Changing only `zoom` zooms the page in place; it doesn't reload. */
  zoom?: number;
}
/** HUP: a real macOS view (WKWebView, PDFView, AVPlayerView, QLPreviewView) placed where this element
 *  is drawn, inside the window. Children draw underneath (shown while it loads or steps aside for a
 *  pane drag). Fireflies' menus, dialogs and windows above it cut a hole in it, so the page keeps
 *  rendering around them and a dialog's backdrop dims it. Same id + same props keeps the view; new props load into it. Not on stock Herdr:
 *  probe with `import * as herdr from "herdr"; if (herdr.nativeView) herdr.nativeView.new(id, props)`. */
export const nativeView: { new: (id: string, props: NativeViewProps) => import("gpui-kit").NativeElement };
/** HUP: `{ interface: "native-view/0", available, kinds: [{ kind, actions }] }`. */
export function nativeViewCapabilities(): { interface: string; platform: string; available: boolean; kinds: { kind: string; actions: string[] }[] };
/** HUP: one whitelisted action on this mod's view `id` (see capabilities), e.g. ("v", "pdf.goToPage", { page: 2 }),
 *  ("v", "media.pause"), ("v", "browser.navigate", { url }), ("v", "state"). Throws on unknown actions. */
export function nativeViewCall(id: string, action: string, args?: Record<string, unknown>): unknown;
/** HUP: the next event from this mod's native views, as JSON text:
 *  `{ id, generation, event, data }` (load.start/commit/finish/error, pdf.page, media.paused, view.created/disposed, …).
 *  Web: `web.location` (the page state, as in load.*) whenever the address or back/forward state changes,
 *  also without a load (pushState, #fragments); `web.video { present }` (`pip: true` views) when the
 *  page gains its first or loses its last `<video>`, in any frame.
 *  `generation` grows with every load, so drop events older than the view's current one. */
export function nextNativeViewEvent(): Promise<string>;
